import json
# eras: 0 ancient world, 1 Middle Ages, 2 early modern period, 3 the 1800s, 4 the 20th century or later
# tuple: (tier, era, question, correct, [3 wrong], fact)
Q=[]
def add(t,e,q,a,w,f):
    assert len(w)==3 and a not in w, q
    Q.append({'t':t,'e':e,'q':q,'a':a,'w':w,'f':f})

